INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Конституционные кейсы: федеральная власть','Региональная дума предлагает признать Совет Федерации высшим федеральным исполнительным органом. Какая правовая квалификация верна?','["Совет Федерации — высший исполнительный орган страны","Совет Федерации — палата Федерального Собрания, осуществляющего законодательную власть","Совет Федерации — орган конституционного контроля","Совет Федерации — самостоятельный уровень местного самоуправления"]'::jsonb,1,'Конституция Российской Федерации','статья 94','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 94 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Проект регламента предлагает включить в Совет Федерации только представителей региональных законодательных органов. Что не учтено?','["От каждого субъекта входят представители законодательного и исполнительного органов","От каждого субъекта назначаются исключительно два региональных депутата","Все сенаторы избираются по единому федеральному округу","Региональные правительства назначают всех сенаторов без участия иных органов"]'::jsonb,0,'Конституция Российской Федерации','статья 95','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 95 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Губернатор предлагает направить в Совет Федерации сразу трёх представителей от своего субъекта. Какое число предусмотрено Конституцией для субъектов?','["Три представителя от каждого субъекта","Число представителей равно числу федеральных округов","Один представитель от каждого субъекта","Два представителя от каждого субъекта"]'::jsonb,3,'Конституция Российской Федерации','статья 95','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 95 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Совет Федерации хочет исключить из своего состава всех назначаемых Президентом представителей Российской Федерации. Какова оценка?','["Президент не имеет полномочий назначать сенаторов РФ","Президент назначает только депутатов Государственной Думы","Конституция допускает представителей РФ, назначаемых Президентом в установленном порядке","Таких сенаторов выбирают исключительно избирательные комиссии"]'::jsonb,2,'Конституция Российской Федерации','статья 95','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 95 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Гражданин 29 лет выдвигается для назначения сенатором. Какое ограничение действует?','["Достаточно 25 лет при наличии юридического стажа","Необходимо достижение 30-летнего возраста","Необходимо достижение 35-летнего возраста","Возраст кандидата на полномочия сенатора не ограничен"]'::jsonb,1,'Конституция Российской Федерации','статья 95','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 95 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Политическая партия утверждает, что Государственная Дума состоит из 400 депутатов, если 50 мандатов зарезервировано для регионов. Какой состав установлен Конституцией?','["450 депутатов Государственной Думы","400 депутатов Государственной Думы","500 депутатов с отдельной квотой для регионов","Число депутатов ежегодно определяет ЦИК"]'::jsonb,0,'Конституция Российской Федерации','статья 96','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 96 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Гражданину 20 лет в день голосования. Он просит зарегистрировать его кандидатом в Госдуму на основании активного избирательного права. Какое различие важно?','["Для голосования и избрания требуется 18 лет","Для голосования и избрания требуется 21 год","Для избрания нужно 25 лет, для голосования — 21","Для избрания депутатом требуется 21 год, для участия в голосовании — 18"]'::jsonb,3,'Конституция Российской Федерации','статья 96','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 96 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Депутат Госдумы приобрёл иностранное гражданство, сохраняя российское. Совместим ли такой статус с конституционными требованиями?','["Да, если иностранное гражданство получено после выборов","Да, при одобрении профильного комитета","Нет, депутат не может иметь иностранное гражданство","Да, если иностранный паспорт хранится за пределами России"]'::jsonb,2,'Конституция Российской Федерации','статья 96','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 96 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Дума старого созыва предлагает продолжать законодательную деятельность после первого заседания вновь избранной Думы. Когда заканчиваются полномочия прежней?','["Через три месяца после выборов независимо от созыва","С момента начала работы Государственной Думы нового созыва","После представления проекта нового федерального бюджета","Когда Совет Федерации утвердит прекращение её полномочий"]'::jsonb,1,'Конституция Российской Федерации','статья 97','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 97 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','После избрания Государственной Думы нового созыва депутаты планируют первое заседание только через сорок дней без специальных решений. Что действует по Конституции?','["На тридцатый день после избрания, если Президент не созвал раньше","Не позднее сорока пяти дней по решению избиркома","Через шестьдесят дней после регистрации последнего депутата","Лишь после утверждения Председателя Правительства"]'::jsonb,0,'Конституция Российской Федерации','статья 97','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 97 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Новый созыв Государственной Думы получил указ Президента о созыве первого заседания раньше тридцатого дня. Допускается ли это?','["Нет, первый созыв всегда начинается ровно на тридцатый день","Да, но только по просьбе Совета Федерации","Нет, время заседания определяет исключительно Правительство","Да, Президент может созвать первое заседание ранее тридцатого дня"]'::jsonb,3,'Конституция Российской Федерации','статья 97','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 97 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Депутата пытаются задержать на протяжении срока полномочий в ситуации, не подпадающей под исключение о задержании на месте преступления. Какое условие существенно?','["Обычное разрешение руководителя парламентской фракции","Согласие главы региональной администрации","Конституционная неприкосновенность и специальная процедура её лишения","Отсутствие необходимости какой-либо парламентской процедуры"]'::jsonb,2,'Конституция Российской Федерации','статья 98','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 98 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Кто решает вопрос лишения сенатора или депутата Госдумы неприкосновенности по представлению Генпрокурора?','["Только Председатель Правительства","Соответствующая палата Федерального Собрания","Центральная избирательная комиссия","Любой региональный законодательный орган"]'::jsonb,1,'Конституция Российской Федерации','статья 98','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 98 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Сенаторы предлагают, чтобы Государственная Дума постоянно заседала на совместных пленарных заседаниях с Советом Федерации как единый орган. Как организована работа палат?','["Палаты Федерального Собрания действуют раздельно","Обе палаты постоянно действуют только совместно","Совместные заседания обязательны для принятия всех федеральных законов","Совместные заседания заменяют любые раздельные сессии"]'::jsonb,0,'Конституция Российской Федерации','статья 99','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 99 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Для ежегодного послания Президента предложено провести совместное заседание палат Федерального Собрания. Позволяет ли это Конституция?','["Нет, совместные заседания палат полностью запрещены","Да, но только с согласия Правительства","Нет, послания рассматриваются исключительно Советом Федерации","Да, палаты могут собираться совместно для заслушивания посланий Президента"]'::jsonb,3,'Конституция Российской Федерации','статья 100','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 100 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Госдума предлагает утвердить регламент Совета Федерации общим постановлением нижней палаты. Какой порядок установлен?','["Регламент верхней палаты утверждает только Госдума","Оба регламента утверждает Правительство","Каждая палата принимает собственный регламент","Регламенты утверждаются региональными парламентами"]'::jsonb,2,'Конституция Российской Федерации','статья 101','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 101 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Депутат предлагает передать председательство в Госдуме назначенному Правительством чиновнику без выборов депутатами. Какое правило нарушается?','["Председателя Госдумы назначает Совет Федерации","Государственная Дума избирает своего Председателя из своего состава","Председателя Госдумы назначает Председатель Правительства","Председателя Госдумы выбирают только субъекты РФ"]'::jsonb,1,'Конституция Российской Федерации','статья 101','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 101 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Правительство подготовило постановление о назначении выборов Президента РФ. Какое конституционное полномочие нарушается?','["Выборы Президента назначает Совет Федерации","Выборы Президента назначает Правительство","Выборы Президента назначает Госдума","Выборы Президента назначает Верховный Суд"]'::jsonb,0,'Конституция Российской Федерации','статья 102','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 102 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Региональный парламент предлагает самостоятельно утвердить указ Президента о введении военного положения. Кто решает вопрос утверждения?','["Государственная Дума","Законодательный орган каждого субъекта отдельно","Правительство Российской Федерации","Совет Федерации"]'::jsonb,3,'Конституция Российской Федерации','статья 102','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 102 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Госдума планирует назначить судью Конституционного Суда по представлению Президента. Какой орган обладает полномочием?','["Государственная Дума","Совет Федерации и Государственная Дума совместным заседанием","Совет Федерации","Совет Безопасности РФ"]'::jsonb,2,'Конституция Российской Федерации','статья 102','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 102 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Президент внёс кандидатуру Генерального прокурора РФ. Какова роль Совета Федерации в установленной Конституцией процедуре?','["Утвердить федеральный закон о персональном назначении","Провести консультации по представленной кандидатуре","Назначить прокурора без участия Президента","Передать решение региональным парламентам"]'::jsonb,1,'Конституция Российской Федерации','статья 102','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 102 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Совет Федерации подготовил постановление об объявлении амнистии. Какая палата вправе объявлять амнистию?','["Государственная Дума","Совет Федерации","Правительство","Конституционный Суд"]'::jsonb,0,'Конституция Российской Федерации','статья 103','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 103 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Кандидатура Председателя Правительства представлена Президентом, но председатель Совета Федерации требует единоличного утверждения. Какая палата утверждает кандидатуру?','["Совет Федерации","Верховный Суд","Государственный Совет","Государственная Дума"]'::jsonb,3,'Конституция Российской Федерации','статья 103','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 103 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Члены правительства хотят заменить ежегодное заслушивание отчётов в Госдуме представлением только в Совет Федерации. Какое полномочие Госдумы затронуто?','["Утверждение указов о военном положении","Назначение президентских выборов","Заслушивание ежегодных отчётов Правительства о результатах деятельности","Назначение судей Конституционного Суда"]'::jsonb,2,'Конституция Российской Федерации','статья 103','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 103 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Федеральное Собрание обсуждает назначение Уполномоченного по правам человека. Кто осуществляет назначение и освобождение?','["Совет Федерации","Государственная Дума","Правительство","Генеральная прокуратура"]'::jsonb,1,'Конституция Российской Федерации','статья 103','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 103 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Региональное законодательное собрание разработало федеральный законопроект о совместном ведении. Куда вносится законопроект?','["В Государственную Думу","В Совет Федерации для первого чтения","В Конституционный Суд для принятия","В Правительство как орган законодательной власти"]'::jsonb,0,'Конституция Российской Федерации','статья 104','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 104 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Депутат Госдумы подготовил законопроект о введении нового федерального налога без заключения Правительства. Что требует Конституция?','["Достаточно заключения Совета Федерации","Заключение требуется только для местных налогов","Заключение заменяется решением бюджетного комитета Госдумы","Законопроекты о введении или отмене налогов могут вноситься только при наличии заключения Правительства"]'::jsonb,3,'Конституция Российской Федерации','статья 104','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 104 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Финансовый законопроект предусматривает расходы за счёт федерального бюджета. Может ли депутат внести его, минуя заключение Правительства?','["Да, любые финансовые законопроекты свободны от такого заключения","Да, если расходы менее миллиарда рублей","Нет, заключение Правительства необходимо","Нет, вместо заключения требуется только указ Президента"]'::jsonb,2,'Конституция Российской Федерации','статья 104','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 104 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Госдума приняла федеральный закон, но решила вообще не направлять его в Совет Федерации. Какой срок передачи предусмотрен?','["В течение десяти дней после принятия","В течение пяти дней после принятия","В течение четырнадцати дней после принятия","Передача необязательна для обычного федерального закона"]'::jsonb,1,'Конституция Российской Федерации','статья 105','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 105 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Совет Федерации отверг обычный федеральный закон. Государственная Дума хочет принять закон повторно в прежней редакции. Какой порог необходим?','["Не менее двух третей от общего числа депутатов","Простое большинство присутствующих депутатов","Три четверти от общего числа сенаторов","Большинство от общего числа депутатов без квалифицированного порога"]'::jsonb,0,'Конституция Российской Федерации','статья 105','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 105 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Совет Федерации не рассмотрел за 14 дней обычный закон, не подлежащий обязательному рассмотрению. Какой результат наступает?','["Закон считается отклонённым","Государственная Дума должна вновь пройти три чтения","Президент обязан распустить Совет Федерации","Закон считается одобренным Советом Федерации"]'::jsonb,3,'Конституция Российской Федерации','статья 105','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 105 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Принят федеральный закон по вопросам ратификации международного договора. Может ли Совет Федерации считать рассмотрение необязательным?','["Да, если договор экономический","Да, если закон ранее рассмотрел профильный комитет Госдумы","Нет, такие законы подлежат обязательному рассмотрению Советом Федерации","Да, если закон не касается бюджета"]'::jsonb,2,'Конституция Российской Федерации','статья 106','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 106 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Госдума приняла закон о статусе и защите государственной границы. Какое правило верхней палаты применяется?','["Автоматическое одобрение независимо от содержания","Обязательное рассмотрение Советом Федерации","Принятие только Госдумой без участия верхней палаты","Утверждение лишь Правительством"]'::jsonb,1,'Конституция Российской Федерации','статья 106','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 106 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Президент отклонил федеральный закон. Обе палаты вновь приняли его в прежней редакции необходимым большинством. Какова дальнейшая обязанность Президента?','["Подписать и обнародовать закон в установленный срок с учётом процедуры конституционного контроля","Назначить новые выборы Госдумы в обязательном порядке","Передать закон Правительству для окончательного принятия","Автоматически прекратить полномочия Совета Федерации"]'::jsonb,0,'Конституция Российской Федерации','статья 107','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 107 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Принятый парламентом федеральный закон направлен Президенту. Какой общий срок для подписания и обнародования?','["Семь дней","Тридцать дней","Два месяца","Четырнадцать дней"]'::jsonb,3,'Конституция Российской Федерации','статья 107','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 107 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Государственная Дума одобрила федеральный конституционный закон 290 голосами из 450, а Совет Федерации поддержал его необходимым большинством. Принят ли ФКЗ?','["Да, достаточно простого большинства от 450","Да, при одобрении Советом Федерации любого большинства","Нет, в Госдуме нужно не менее 300 голосов","Нет, в Госдуме необходимо не менее 338 голосов"]'::jsonb,2,'Конституция Российской Федерации','статья 108','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 108 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','В Совете Федерации 178 сенаторов. За ФКЗ проголосовали 130, в Госдуме набраны две трети. Какой вывод?','["Достаточно простого большинства Совета Федерации","Не хватает голосов Совета Федерации: необходимо не менее 134","Не хватает голосов Госдумы независимо от их количества","Достаточно 120 голосов сенаторов"]'::jsonb,1,'Конституция Российской Федерации','статья 108','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 108 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Государственная Дума избрана восемь месяцев назад. Президент рассматривает её роспуск по основанию статьи 117. Какое ограничение действует?','["В течение года после избрания роспуск по основанию статьи 117 недопустим","Роспуск запрещён только первые три месяца","Роспуск запрещён лишь при принятом бюджете","Президент не может распустить Думу при любых обстоятельствах"]'::jsonb,0,'Конституция Российской Федерации','статья 109','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 109 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Президент хочет распустить Государственную Думу за четыре месяца до окончания своего срока. Каков конституционный запрет?','["Роспуск запрещён лишь в последний месяц","Роспуск допускается при любом сроке без ограничений","Ограничение действует только по окончании полномочий Госдумы","Роспуск не допускается в течение шести месяцев до окончания президентских полномочий"]'::jsonb,3,'Конституция Российской Федерации','статья 109','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 109 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Региональный парламент объявил, что федеральная исполнительная власть осуществляется Федеральным Собранием. Какая конституционная модель действует?','["Исполнительную власть осуществляет только Государственная Дума","Исполнительную власть осуществляет только Совет Федерации","Исполнительную власть осуществляет Правительство РФ под общим руководством Президента","Исполнительную власть осуществляют исключительно органы субъектов"]'::jsonb,2,'Конституция Российской Федерации','статья 110','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 110 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Государственная Дума трижды отклонила предложенные кандидатуры Председателя Правительства. Кто далее назначает Председателя?','["Совет Федерации","Президент без утверждения Государственной Думой","Председатель Госдумы своим постановлением","Правительство в качестве коллегии"]'::jsonb,1,'Конституция Российской Федерации','статья 111','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 111 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Председатель Правительства после назначения не представил Президенту предложения о структуре федеральных органов исполнительной власти. Какой общий срок на представление?','["Не позднее недельного срока после назначения с учётом конституционных исключений","Не позднее месяца после назначения","Не позднее тридцати дней после первого заседания Госдумы","Не позднее трёх месяцев после утверждения бюджета"]'::jsonb,0,'Конституция Российской Федерации','статья 112','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 112 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Кандидатуру министра обороны предлагают провести только через утверждение Госдумой как обычного министра. Какой специальный конституционный порядок действует?','["Правительство назначает министра без участия Президента","Госдума назначает министра своим постановлением","Совет Федерации назначает без представления Президента","Президент назначает после консультаций с Советом Федерации"]'::jsonb,3,'Конституция Российской Федерации','статья 112','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 112 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Федеральное министерство собирается представить проект федерального бюджета непосредственно Совету Федерации. Какой орган разрабатывает и куда представляет бюджет?','["Совет Федерации разрабатывает и представляет Президенту","Государственная Дума представляет проект в Конституционный Суд","Правительство разрабатывает и представляет Государственной Думе","Министерство финансов вносит бюджет только в Совет Федерации"]'::jsonb,2,'Конституция Российской Федерации','статья 114','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 114 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Правительство полагает, что не обязано представлять Госдуме отчёт об исполнении федерального бюджета. Какое полномочие закреплено Конституцией?','["Правительство представляет отчёт только Совету Федерации","Правительство представляет Государственной Думе отчёт об исполнении федерального бюджета","Отчёт обязаны готовить исключительно региональные парламенты","Федеральный бюджет не требует отчёта об исполнении"]'::jsonb,1,'Конституция Российской Федерации','статья 114','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 114 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Постановление Правительства противоречит федеральному закону. Кто вправе отменить его в рамках конституционных полномочий?','["Президент Российской Федерации","Председатель Госдумы единолично","Только глава субъекта РФ","Исключительно Центральная избирательная комиссия"]'::jsonb,0,'Конституция Российской Федерации','статья 115','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 115 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Правительство намерено издать нормативный акт не в установленной форме постановления или распоряжения. Какие акты предусмотрены Конституцией?','["Указы и федеральные законы","Судебные приговоры и определения","Федеральные конституционные законы и уставы","Постановления и распоряжения"]'::jsonb,3,'Конституция Российской Федерации','статья 115','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 115 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','После вступления нового Президента в должность действующее Правительство решило не слагать полномочия до завершения бюджетного года. Какое правило действует?','["Полномочия слагаются только при избрании новой Госдумы","Полномочия слагаются только после решения Конституционного Суда","Правительство слагает полномочия перед вновь избранным Президентом","Правительство не слагает полномочий в связи с выборами Президента"]'::jsonb,2,'Конституция Российской Федерации','статья 116','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 116 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Государственная Дума выразила недоверие Правительству впервые. Какое решение вправе принять Президент?','["Обязан в тот же день распустить Государственную Думу","Объявить об отставке Правительства либо не согласиться с решением Госдумы","Обязан передать решение только Совету Федерации","Может отменить Конституцию на время конфликта"]'::jsonb,1,'Конституция Российской Федерации','статья 117','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 117 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','В течение трёх месяцев Госдума повторно выразила недоверие Правительству. Какие варианты предусмотрены Конституцией?','["Президент объявляет об отставке Правительства либо распускает Госдуму с назначением новых выборов","Президент обязан принять только отставку Председателя Госдумы","Государственная Дума обязана самостоятельно назначить всех министров","Совет Федерации решает судьбу Правительства без участия Президента"]'::jsonb,0,'Конституция Российской Федерации','статья 117','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 117 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','Председатель Правительства поставил перед Госдумой вопрос о доверии. Каким конституционным сроком ограничено его рассмотрение?','["В течение четырнадцати дней","В течение тридцати дней","В течение трёх месяцев","В течение семи дней"]'::jsonb,3,'Конституция Российской Федерации','статья 117','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 117 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true),
('Конституционные кейсы: федеральная власть','При отказе Госдумы в доверии Правительству Президент рассматривает варианты. Какой общий срок принятия решения?','["В течение тридцати дней","В течение шестидесяти дней","В течение семи дней","В течение трёх месяцев"]'::jsonb,2,'Конституция Российской Федерации','статья 117','https://www.consultant.ru/document/cons_doc_LAW_28399/','Применяется статья 117 Конституции РФ: необходимо разграничить компетенцию, установленное большинство и правовую процедуру.',true)
